    '{\n  "id": "storage",\n  "name": {\n    "en": "Private files",\n    "zh-CN": "私有文件"\n  },\n  "description": {\n    "en": "Private S3, R2, OSS or COS uploads and owned downloads",\n    "zh-CN": "S3、R2、OSS 或 COS 私有上传与个人文件下载"\n  },\n  "category": "content",\n  "requires": ["auth"],\n  "supports": {\n    "frameworks": ["next", "tanstack-start", "nuxt"],\n    "backends": ["self"],\n    "apis": ["none"],\n    "orms": ["drizzle"],\n    "dialects": ["sqlite", "postgres"]\n  },\n  "nativeSplit": true,\n  "providers": {\n    "min": 1,\n    "max": 1,\n    "default": {\n      "global": ["s3"],\n      "cn": ["oss"]\n    },\n    "targetDefaults": {\n      "cloudflare": ["r2-binding"]\n    },\n    "options": {\n      "s3": {\n        "name": "Amazon S3",\n        "market": "global",\n        "supports": {\n          "targets": ["none", "node", "vercel", "docker"]\n        },\n        "dependencies": {\n          "@aws-sdk/client-s3": "^3.1000.0",\n          "@aws-sdk/s3-request-presigner": "^3.1000.0"\n        },\n        "env": [\n          {\n            "key": "S3_REGION",\n            "required": false,\n            "sensitive": false\n          },\n          {\n            "key": "S3_BUCKET",\n            "required": false,\n            "sensitive": false\n          },\n          {\n            "key": "S3_ACCESS_KEY_ID",\n            "required": false\n          },\n          {\n            "key": "S3_SECRET_ACCESS_KEY",\n            "required": false\n          },\n          {\n            "key": "S3_SESSION_TOKEN",\n            "required": false\n          }\n        ]\n      },\n      "r2": {\n        "name": "Cloudflare R2 (S3 API)",\n        "market": "global",\n        "supports": {\n          "targets": ["none", "node", "vercel", "docker"]\n        },\n        "dependencies": {\n          "@aws-sdk/client-s3": "^3.1000.0",\n          "@aws-sdk/s3-request-presigner": "^3.1000.0"\n        },\n        "env": [\n          {\n            "key": "R2_ACCOUNT_ID",\n            "required": false,\n            "sensitive": false\n          },\n          {\n            "key": "R2_BUCKET",\n            "required": false,\n            "sensitive": false\n          },\n          {\n            "key": "R2_ACCESS_KEY_ID",\n            "required": false\n          },\n          {\n            "key": "R2_SECRET_ACCESS_KEY",\n            "required": false\n          }\n        ]\n      },\n      "r2-binding": {\n        "name": "Cloudflare R2 (Workers binding)",\n        "market": "global",\n        "supports": {\n          "frameworks": ["next"],\n          "targets": ["cloudflare"]\n        },\n        "dependencies": {\n          "@opennextjs/cloudflare": "$dependency:@opennextjs/cloudflare"\n        },\n        "devDependencies": {\n          "@cloudflare/workers-types": "$dependency:@cloudflare/workers-types"\n        }\n      },\n      "oss": {\n        "name": "Alibaba Cloud OSS",\n        "market": "cn",\n        "supports": {\n          "targets": ["none", "node", "vercel", "docker"]\n        },\n        "dependencies": {\n          "ali-oss": "^6.23.0"\n        },\n        "devDependencies": {\n          "@types/ali-oss": "^6.23.3"\n        },\n        "appDependencies": {\n          "ali-oss": "^6.23.0"\n        },\n        "serverExternalPackages": ["ali-oss"],\n        "env": [\n          {\n            "key": "OSS_REGION",\n            "required": false,\n            "sensitive": false\n          },\n          {\n            "key": "OSS_BUCKET",\n            "required": false,\n            "sensitive": false\n          },\n          {\n            "key": "OSS_ACCESS_KEY_ID",\n            "required": false\n          },\n          {\n            "key": "OSS_ACCESS_KEY_SECRET",\n            "required": false\n          },\n          {\n            "key": "OSS_SECURITY_TOKEN",\n            "required": false\n          }\n        ]\n      },\n      "cos": {\n        "name": "Tencent Cloud COS",\n        "market": "cn",\n        "supports": {\n          "targets": ["none", "node", "vercel", "docker"]\n        },\n        "dependencies": {\n          "cos-nodejs-sdk-v5": "^3.0.0"\n        },\n        "env": [\n          {\n            "key": "COS_REGION",\n            "required": false,\n            "sensitive": false\n          },\n          {\n            "key": "COS_BUCKET",\n            "required": false,\n            "sensitive": false\n          },\n          {\n            "key": "COS_SECRET_ID",\n            "required": false\n          },\n          {\n            "key": "COS_SECRET_KEY",\n            "required": false\n          },\n          {\n            "key": "COS_SECURITY_TOKEN",\n            "required": false\n          }\n        ]\n      }\n    }\n  },\n  "packages": [\n    {\n      "dir": "storage",\n      "dependencies": {\n        "drizzle-orm": "$dependency:drizzle-orm",\n        "zod": "$dependency:zod"\n      },\n      "workspaceDependencies": ["db"]\n    }\n  ],\n  "appDependencies": {\n    "zod": "$dependency:zod"\n  },\n  "services": [\n    {\n      "name": "storage",\n      "imports": [\n        {\n          "from": "@app/storage",\n          "names": ["createStorage"]\n        }\n      ],\n      "init": "createStorage({ env: ENV, db })"\n    }\n  ],\n  "nav": [\n    {\n      "area": "dashboard",\n      "href": "/dashboard/files",\n      "labelKey": "nav.files",\n      "order": 60\n    }\n  ],\n  "sources": {\n    "dialects": true,\n    "frameworks": ["http-server", "next", "nuxt", "tanstack-start", "react"],\n    "frameworkRequired": {\n      "http-server": [\n        "frameworks/http-server/apps/{application}/src/lib/native/storage.ts.hbs",\n        "frameworks/http-server/apps/{application}/src/lib/storage-http.ts.hbs",\n        "shared/partials/storage.hbs",\n        "shared/partials/storage-http.hbs"\n      ],\n      "next": ["shared/partials/storage-http.hbs"],\n      "react": ["shared/partials/file-manager.hbs"]\n    },\n    "providers": {\n      "mode": "inline",\n      "source": "files/packages/storage/src/provider.ts.hbs"\n    }\n  }\n}\n',
